import json, os

paths = [
    '/root/autodl-tmp/exp003/rrf_full_n_latest/exposure_scores.json',
    '/root/autodl-tmp/exp003/rrf_n20_all/exposure_scores.json',
]
for p in paths:
    if os.path.exists(p):
        print(f'=== {p} ===')
        with open(p) as f:
            data = json.load(f)
        print(f'Top-level type: {type(data).__name__}, keys: {list(data.keys())[:10]}')
        for key in list(data.keys())[:3]:
            val = data[key]
            print(f'  {key}: type={type(val).__name__}', end='')
            if isinstance(val, dict):
                print(f', keys={list(val.keys())[:5]}', end='')
                for k2 in list(val.keys())[:2]:
                    v2 = val[k2]
                    if isinstance(v2, dict):
                        print(f'\n    {k2}: keys={list(v2.keys())[:5]}', end='')
                    elif isinstance(v2, list):
                        print(f'\n    {k2}: list len={len(v2)}', end='')
            elif isinstance(val, list):
                print(f', len={len(val)}', end='')
            print()
        print('\n=== Per-benchmark respondent count ===')
        if isinstance(data, dict):
            first_key = list(data.keys())[0]
            first_val = data[first_key]
            if isinstance(first_val, dict):
                benchmarks = set()
                for model, bdata in data.items():
                    if isinstance(bdata, dict):
                        benchmarks.update(bdata.keys())
                for bench in sorted(benchmarks):
                    count = sum(1 for m, bd in data.items() if isinstance(bd, dict) and bench in bd)
                    print(f'  {bench}: N={count} respondents')
                print(f'\nTotal models: {len(data)}')
                print(f'Model names: {list(data.keys())}')
        print()
